from lib import *
S = SS('p29')
steps = [
    step("设置:200 个客户端同时开始,每个只要成功一次;服务器前 1 秒整体故障(回 503),之后同时处理超过 20 个请求就回 503;每个客户端最多尝试 12 次。立刻重试:服务器收到 2400 个请求(200×12),任意 0.1 秒内最多 994 个,200 个客户端全部在故障期内用完 12 次后放弃。固定延迟 0.5 秒:1260 个请求,4.8 秒全部成功,但每 0.5 秒都是 200 个客户端同时到达(0.1 秒内最多 200)。指数退避(无抖动):1766 个请求,0.1 秒内最多 200,31.6 秒才结束,而且 26 个客户端用完 12 次也没成功;完全抖动:1167 个请求,5.3 秒全部成功,0.1 秒内最多 411(开头的集中请求),任何客户端最多尝试 8 次;去相关抖动:918 个请求,2.9 秒全部成功,最多尝试 8 次。", t=tl(S(1)), done=lidx(S(1), '指数退避 + 完全抖动', '去相关抖动'), mark=lidx(S(1), '立刻重试', '指数退避(无抖动)'), b=bars([['立刻重试:服务器收到', 2400, '2400'], ['固定 0.5 秒', 1260, '1260'], ['指数无抖动', 1766, '1766'], ['完全抖动', 1167, '1167'], ['去相关抖动', 918, '918']], 2400, mark=[0, 2], done=[3, 4]), kv=KV([['立刻重试', '2400 个请求,200 个全放弃'], ['指数无抖动', '31.6 秒,26 个放弃'], ['去相关抖动', '918 个请求,2.9 秒完成']], ['指数无抖动'])),
    step("同一种策略换 4 个随机种子重复,看稳不稳:指数退避(无抖动)服务器收到 1570、1438、1840、1840 个请求,任意 0.1 秒内始终正好 200 个(200 个客户端同步),全部成功于 31.6、26.5、31.6、31.6 秒;指数退避加完全抖动:1165、1194、1168、1184 个请求,0.1 秒内最多 339–390,全部成功于 3.8–4.6 秒。无抖动版本的“同步”不随种子变化:它们本来就没有用到随机数,每一轮都是 200 个同时重来;加了抖动之后,重试被打散。", t=tl(S(2)), done=lidx(S(2), '指数退避 + 完全抖动'), mark=lidx(S(2), '指数退避(无抖动)'), b=bars([['无抖动:0.1 秒内最多(4 个种子)', 200, '200'], ['完全抖动:0.1 秒内最多(最大)', 390, '390'], ['无抖动:完成 秒(最长)', 31.6, '31.6'], ['完全抖动:完成 秒(最长)', 4.6, '4.6']], 400, mark=[0, 2], done=[3]), kv=KV([['无抖动', '每轮 200 个同时重来'], ['完全抖动', '3.8–4.6 秒完成'], ['种子', '无抖动不受随机种子影响']], ['无抖动'])),
]
A = mkartp('p29', 29, '爬虫,重试,指数退避,抖动,jitter,惊群,asyncio,Python,真实验证,动画演示',
    '200 个客户端同时遇到 1 秒故障的模拟:立刻重试向服务器砸了 2400 个请求且全部放弃;没有抖动的指数退避让 200 个客户端每轮同时重来,31.6 秒才结束还有 26 个放弃;加完全抖动 5.3 秒、去相关抖动 2.9 秒全部成功。',
    '“失败了就指数退避”是重试的标准答案,但如果所有客户端同时开始、同时失败,没有抖动的指数退避只是让它们每一轮同时回来一次。这篇用 200 个客户端和一个先故障后限流的本机服务器,把五种策略在服务器端打出的请求节奏量出来。',
    [('26', '无抖动的指数退避下,12 次尝试用完仍然没成功的客户端数(完全抖动是 0)'), ('200', '无抖动的指数退避和固定延迟下,任意 0.1 秒内服务器收到的请求数——200 个客户端同步'), ('2.9 秒', '去相关抖动让全部 200 个客户端成功所用的时间(无抖动指数退避 31.6 秒)')],
    [('五种策略的节奏', '<p><b>立刻重试</b>:12 次机会在 1 秒的故障期内就用光,服务器总共收到 2400 个请求,任意 0.1 秒内最多 994 个,200 个客户端全部放弃。重试而没有间隔,等于对已经出问题的服务器加压。</p><p><b>固定间隔与无抖动的指数退避</b>:固定 0.5 秒时 200 个客户端每 0.5 秒同时回来一次;服务器每轮只能处理 20 个。无抖动的指数退避看起来更“聪明”,但所有客户端同步,每一轮仍是 200 个同时到达,间隔越来越长而一轮只成功 20 个,最后 26 个客户端用完 12 次也没成功,总共 31.6 秒。</p><p><b>加抖动</b>:完全抖动(在 0 到退避上限之间随机)5.3 秒全部成功;去相关抖动(下一次等待取决于上一次)2.9 秒、只用 918 个请求。开头的 0.1 秒内仍有 200–400 个请求,因为所有客户端是同时开始的——抖动解决的是后续重试的同步,不能消除一开始的集中。</p>'),
     ('换随机种子,以及结果的波动', '<p>无抖动的指数退避不依赖随机数,4 个种子下任意 0.1 秒内都是正好 200 个(客户端同步),完成时间 26.5–31.6 秒;完全抖动 3.8–4.6 秒。服务器“同时处理超过 20 个就拒绝”依赖线程调度,所以每次运行细节不同:我把整个脚本跑了两遍,固定间隔 5.8 秒与 4.8 秒,完全抖动 5.6 秒与 5.3 秒,去相关抖动 3.6 秒与 2.9 秒,无抖动指数退避放弃的客户端 20 个与 26 个;文中取第二遍。不变的结论是:无抖动同步重试最慢,抖动最快。</p>')],
    steps,
    [ENV_P + '。服务器:启动后前 1.0 秒对所有请求回 503,之后若同时在处理的请求数超过 20 就立刻回 503,否则处理 0.05 秒后回 200;200 个 aiohttp 客户端同时开始、各自重试至多 12 次;退避基数 0.1 秒、上限 5 秒;抖动用固定种子的随机数;服务器收到的请求数、0.1 秒窗口内的最大值由服务器记录的时间戳统计;文中的数字来自最后一次运行(整个脚本跑了两遍,第一遍的数字在上面的说明里标出)',
     '没有验证:真实服务器对 429、Retry-After 的处理(下一篇讲);重试预算(限制总重试比例)与断路器;不同故障形态(慢而不是错)下的表现;客户端数量更大(几千)时的节奏;非幂等请求重试的风险(再下一篇)'],
    '重试与退避')
